// Des: Cron parse, validate, match and next-minute search
// Flo: split fields > validate per field > match vs Local > scan next stamp
// I/O: cron string + Local > bool fire-now, or next minute stamp
// ===================================================================
const std = @import("std"); const base = @import("tk-time-base.zig"); const CF = base.CF; const Local = base.Local; const daysFromCivil = base.daysFromCivil; const localFromMinuteStamp = base.localFromMinuteStamp;
pub const CronFields = [5][]const u8;
pub const CronError = error{ WrongFieldCount, BadField, OutOfRange, BadStep, BadRange };
pub fn parseCron(sche: []const u8) CronError!CronFields { var fiel: CronFields = undefined; var coun: usize = 0; var iter = std.mem.tokenizeAny(u8, sche, CF.trim); while (iter.next()) |item| { if (coun >= 5) return CronError.WrongFieldCount; fiel[coun] = item; coun += 1; } if (coun != 5) return CronError.WrongFieldCount; for (fiel, 0..) |item, indx| try fielVali(item, CF.cron_minz[indx], CF.cron_maxz[indx], indx <= 1); return fiel; }
fn partNext(fiel: []const u8, posi: *usize) ?[]const u8 { if (posi.* > fiel.len) return null; const star = posi.*; var dept: u8 = 0; var indx = star; while (indx < fiel.len) : (indx += 1) { const byte = fiel[indx]; if (byte == '[') dept += 1; if (byte == ']') dept -|= 1; if (byte == ',' and dept == 0) break; } posi.* = indx + 1; return fiel[star..indx]; }
fn grouChec(part: []const u8) bool { return part.len >= 2 and part[0] == '[' and part[part.len - 1] == ']'; }
fn rangPars(raw: []const u8) ?[2]i64 { const strn = std.mem.trim(u8, raw, CF.trim); const dots = std.mem.indexOf(u8, strn, "..") orelse return null; const lowz = std.fmt.parseInt(i64, strn[0..dots], 10) catch return null; const higz = std.fmt.parseInt(i64, strn[dots + 2 ..], 10) catch return null; if (lowz > higz) return null; return .{ lowz, higz }; }
fn itemPars(raw: []const u8) ?[2]i64 { const item = std.mem.trim(u8, raw, CF.trim); if (std.mem.indexOf(u8, item, "..") != null) return rangPars(item); if (std.mem.indexOfScalar(u8, item, '-')) |dash| { const lowz = std.fmt.parseInt(i64, item[0..dash], 10) catch return null; const higz = std.fmt.parseInt(i64, item[dash + 1 ..], 10) catch return null; return .{ lowz, higz }; } const valu = std.fmt.parseInt(i64, item, 10) catch return null; return .{ valu, valu }; }
fn grouMatc(inne: []const u8, indx: u64, seed: u64, valu: i64) bool { var coun: u64 = 0; var iter = std.mem.splitScalar(u8, inne, ','); while (iter.next()) |part| { const rang = itemPars(part) orelse return false; coun += @intCast(rang[1] - rang[0] + 1); } if (coun == 0) return false; var hash = std.hash.Wyhash.init(seed); hash.update(inne); hash.update(std.mem.asBytes(&indx)); var pick = hash.final() % coun; iter = std.mem.splitScalar(u8, inne, ','); while (iter.next()) |part| { const rang = itemPars(part) orelse return false; const size: u64 = @intCast(rang[1] - rang[0] + 1); if (pick < size) return rang[0] + @as(i64, @intCast(pick)) == valu; pick -= size; } return false; }
fn fielVali(fiel: []const u8, lowz: i64, higz: i64, grou: bool) CronError!void { if (fiel.len == 0) return CronError.BadField; if (std.mem.eql(u8, fiel, "*")) return; var posi: usize = 0; var anyz = false; while (partNext(fiel, &posi)) |raw| { const part = std.mem.trim(u8, raw, CF.trim); if (part.len == 0) return CronError.BadField; anyz = true; if (std.mem.indexOfAny(u8, part, "[]") != null) { const inne = if (grou and grouChec(part)) part[1 .. part.len - 1] else return CronError.BadField; if (std.mem.indexOfAny(u8, inne, "[]*/") != null) return CronError.BadField; var iter = std.mem.splitScalar(u8, inne, ','); while (iter.next()) |item| { const rang = itemPars(item) orelse return CronError.BadField; if (rang[0] > rang[1]) return CronError.BadRange; if (rang[0] < lowz or rang[1] > higz) return CronError.OutOfRange; } continue; } var body = part; if (std.mem.indexOfScalar(u8, part, '/')) |slas| { body = part[0..slas]; const sstr = part[slas + 1 ..]; const step = std.fmt.parseInt(i64, sstr, 10) catch return CronError.BadStep; if (step <= 0) return CronError.BadStep; if (body.len == 0) return CronError.BadField; } if (std.mem.eql(u8, body, "*")) continue; if (std.mem.indexOfScalar(u8, body, '-')) |dash| { const lowv = std.fmt.parseInt(i64, body[0..dash], 10) catch return CronError.BadField; const higv = std.fmt.parseInt(i64, body[dash + 1 ..], 10) catch return CronError.BadField; if (lowv > higv) return CronError.BadRange; if (lowv < lowz or higv > higz) return CronError.OutOfRange; } else { const valu = std.fmt.parseInt(i64, body, 10) catch return CronError.BadField; if (valu < lowz or valu > higz) return CronError.OutOfRange; } } if (!anyz) return CronError.BadField; }
fn fielMatc(fiel: []const u8, valu: i64, seed: u64) bool { if (std.mem.eql(u8, fiel, "*")) return true; var posi: usize = 0; var grou: u64 = 0; while (partNext(fiel, &posi)) |raw| { const part = std.mem.trim(u8, raw, CF.trim); if (grouChec(part)) { if (grouMatc(part[1 .. part.len - 1], grou, seed, valu)) return true; grou += 1; continue; } var body = part; var step: i64 = 1; if (std.mem.indexOfScalar(u8, part, '/')) |slas| { body = part[0..slas]; step = std.fmt.parseInt(i64, part[slas + 1 ..], 10) catch 1; if (step <= 0) step = 1; } if (std.mem.eql(u8, body, "*")) { if (@mod(valu, step) == 0) return true; continue; } if (std.mem.indexOfScalar(u8, body, '-')) |dash| { const lowz = std.fmt.parseInt(i64, body[0..dash], 10) catch continue; const higz = std.fmt.parseInt(i64, body[dash + 1 ..], 10) catch continue; if (valu >= lowz and valu <= higz and @mod(valu - lowz, step) == 0) return true; } else { const numb = std.fmt.parseInt(i64, body, 10) catch continue; if (step == 1) { if (numb == valu) return true; } else if (valu >= numb and @mod(valu - numb, step) == 0) return true; } } return false; }
pub fn cronMatch(fiel: CronFields, nowz: Local) bool { const seed: u64 = @intCast(daysFromCivil(nowz.year, nowz.month, nowz.day)); if (!fielMatc(fiel[0], nowz.minute, seed *% 31 +% nowz.hour)) return false; if (!fielMatc(fiel[1], nowz.hour, seed)) return false; if (!fielMatc(fiel[3], nowz.month, 0)) return false; const mday_star = std.mem.eql(u8, fiel[2], "*"); const wday_star = std.mem.eql(u8, fiel[4], "*"); const mday_hits = fielMatc(fiel[2], nowz.day, 0); const wday_hits = fielMatc(fiel[4], nowz.weekday, 0) or (nowz.weekday == 0 and fielMatc(fiel[4], 7, 0)); if (mday_star and wday_star) return true; if (mday_star) return wday_hits; if (wday_star) return mday_hits; return mday_hits or wday_hits; }
pub fn nextCronMinute(fiel: CronFields, from: Local) ?i64 { var stam = from.minute_stamp + 1; var indx: i64 = 0; while (indx < CF.scan) : (indx += 1) { if (cronMatch(fiel, localFromMinuteStamp(stam))) return stam; stam += 1; } return null; }
